    (XS.size ? (X.length ? (XS.has('a') ? ` · 💧 ${onA.length.toLocaleString('es-ES')} de agua` : '') + (XS.has('s') ? ` · 🚐 ${onS.length.toLocaleString('es-ES')} vaciados` : '') : ' · cargando agua y servicios…') : '');   // E-093 (v1.46): solo las capas encendidas
